    R2: "| Dm9 | G13 | Dm9 | G13 | Em9 | A7b13 | Bbmaj7#11 | A7#9 |",
    L1: "| Cmaj9 | Fmaj7#11 | Cmaj9 | Fmaj7#11 | Em9 | Am9 | Dm9 | G13sus4 |",
