      const keep = all.filter((x) => !all.some((y) => y.vi !== x.vi && (y.t < x.t || (y.t === x.t && y.vi < x.vi)) && y.t + y.ring > x.t + 0.25
        && Math.abs(y.note - x.note) < 25 && (Math.abs(y.note - x.note) % 12 === 1 || Math.abs(y.note - x.note) % 12 === 11)));
