      "G5/1.5 E5/0.5 G5/1 C6/1",
      "B5/0.5 G5/0.5 B5/0.5 D6/1 B5/0.5 A5/0.5 G5/0.5",
      "A5/3 r/1",
      "A5/0.5 F#5/0.5 A5/0.5 B5/1 A5/0.5 F#5/0.5 E5/0.5",
      "G5/1.5 E5/0.5 C6/1 B5/0.5 G5/0.5",
      "D6/1.5 B5/0.5 G5/1 B5/1",
