      I.send(ctx, sp, hall, -8); I.send(ctx, scanPan, echo, -14); I.send(ctx, scanPan, hall, -16);
      I.send(ctx, hp, hall, -6); I.send(ctx, kp, room, -12); I.send(ctx, kp, hall, -24);

